r = redis.Redis()

def claim(key: str, ttl_ms: int) -> bool:
    return bool(r.set(f"seen:{key}", "1", nx=True, px=ttl_ms))

def handle(msg: Message) -> None:
    if not claim(msg.key, REDELIVERY_WINDOW_MS):
        return ack(msg)                        # duplicate: absorb
    apply_effects(msg)
    ack(msg)

_seen: set[str] = set()

def claim(key: str) -> bool:
    if key in _seen:
        return False
    _seen.add(key)          # GIL-atomic pair: no I/O between check and add
    return True
